"""Only runs against the disposable stack generated by run_integration.py."""

import os
from concurrent.futures import ThreadPoolExecutor
from datetime import UTC, datetime, timedelta
from pathlib import Path
from uuid import uuid4

import httpx
import pytest
from alembic import command
from alembic.config import Config
from sqlalchemy import MetaData, Table, create_engine, text
from sqlalchemy.orm import Session

pytestmark = [
    pytest.mark.integration,
    pytest.mark.skipif(
        os.getenv("QALAPULSE_INTEGRATION_ISOLATED") != "1", reason="Requires isolated test stack"
    ),
]


def test_postgres_reset_is_single_use_and_serializes_refresh():
    from app.core.security import digest
    from app.db.models import PasswordReset

    engine = create_engine(os.environ["INTEGRATION_DATABASE_URL"])
    api_url = os.environ["INTEGRATION_API_URL"]
    with httpx.Client(base_url=api_url, timeout=20) as client:
        email = f"reset-{uuid4().hex}@example.com"
        account = client.post(
            "/auth/register",
            json={
                "email": email,
                "password": "Test-only-reset-2026!",
                "display_name": "Reset test",
            },
        ).json()
        from uuid import UUID

        user_id = UUID(account["user"]["id"])
        token = uuid4().hex + uuid4().hex
        with Session(engine) as db:
            db.add(
                PasswordReset(
                    user_id=user_id,
                    token_hash=digest(token),
                    expires_at=datetime.now(UTC) + timedelta(minutes=5),
                )
            )
            db.commit()

        def reset():
            return client.post(
                "/auth/reset-password", json={"token": token, "password": "Updated-reset-2026!"}
            )

        with ThreadPoolExecutor(max_workers=2) as pool:
            outcomes = list(pool.map(lambda _: reset().status_code, range(2)))
        assert sorted(outcomes) == [200, 400]
        assert (
            client.get(
                "/users/me", headers={"Authorization": f"Bearer {account['access_token']}"}
            ).status_code
            == 401
        )
        current = client.post(
            "/auth/login", json={"email": email, "password": "Updated-reset-2026!"}
        ).json()
        token = uuid4().hex + uuid4().hex
        with Session(engine) as db:
            db.add(
                PasswordReset(
                    user_id=user_id,
                    token_hash=digest(token),
                    expires_at=datetime.now(UTC) + timedelta(minutes=5),
                )
            )
            db.commit()
        with ThreadPoolExecutor(max_workers=2) as pool:
            resetting = pool.submit(reset)
            refreshing = pool.submit(
                client.post, "/auth/refresh", json={"refresh_token": current["refresh_token"]}
            )
            reset_result, refresh_result = resetting.result(), refreshing.result()
        assert reset_result.status_code == 200
        assert refresh_result.status_code in (200, 401)
        if refresh_result.status_code == 200:
            issued = refresh_result.json()
            assert (
                client.get(
                    "/users/me", headers={"Authorization": f"Bearer {issued['access_token']}"}
                ).status_code
                == 401
            )
            assert (
                client.post(
                    "/auth/refresh", json={"refresh_token": issued["refresh_token"]}
                ).status_code
                == 401
            )
    engine.dispose()


def test_postgres_migration_preserves_legacy_confirmations():
    engine = create_engine(
        os.environ["INTEGRATION_DATABASE_URL"], connect_args={"connect_timeout": 10}
    )
    schema = f"migration_check_{uuid4().hex}"
    with engine.connect() as connection:
        connection.execute(text(f"CREATE SCHEMA {schema}"))
        connection.execute(text(f"SET search_path TO {schema}, public"))
        connection.commit()
        config = Config(str(Path(__file__).parents[1] / "alembic.ini"))
        config.set_main_option(
            "script_location", str(Path(__file__).parents[1] / "app/db/migrations")
        )
        config.attributes.update(connection=connection, version_table_schema=schema)
        try:
            command.upgrade(config, "0001")
            meta = MetaData(schema=schema)
            tables = {
                name: Table(name, meta, autoload_with=connection)
                for name in ("users", "categories", "incidents", "incident_confirmations")
            }
            user_id, incident_id, confirmation_id = uuid4(), uuid4(), uuid4()
            now = datetime.now(UTC)
            connection.execute(
                tables["categories"]
                .insert()
                .values(
                    id="other",
                    code="other",
                    name_ru="Тест",
                    name_kk="Сынақ",
                    description="Synthetic",
                    base_severity=3,
                    icon="other",
                    color="#123456",
                    is_active=True,
                )
            )
            connection.execute(
                tables["users"]
                .insert()
                .values(
                    id=user_id,
                    email="legacy@example.com",
                    password_hash="synthetic-not-a-password",
                    display_name="Legacy",
                    preferred_language="ru",
                    role="citizen",
                    is_active=True,
                    created_at=now,
                    updated_at=now,
                )
            )
            # Geography is sent as EWKT through SQL to avoid reflection type assumptions.
            connection.execute(
                text(
                    "INSERT INTO incidents (id, author_id, source, category_id, title, description, latitude, longitude, location, address, severity, priority_score, priority_explanation, status, is_published, is_hidden, confirmation_count, created_at, updated_at) VALUES (:id, :author, 'citizen', 'other', 'Legacy', 'Synthetic', 43.2, 76.8, ST_GeogFromText('SRID=4326;POINT(76.8 43.2)'), '', 3, 30, '{}', 'resolved_pending_confirmation', true, false, 1, :now, :now)"
                ),
                {"id": incident_id, "author": user_id, "now": now},
            )
            connection.execute(
                tables["incident_confirmations"]
                .insert()
                .values(
                    id=confirmation_id,
                    incident_id=incident_id,
                    user_id=user_id,
                    status="still_exists",
                    comment="Preserve me",
                    created_at=now,
                )
            )
            connection.commit()
            command.upgrade(config, "head")
            media_table = Table("incident_media", MetaData(schema=schema), autoload_with=connection)
            assert media_table.c.media_type.type.length == 20
            row = connection.execute(
                text("SELECT id, comment, resolution_cycle FROM incident_confirmations")
            ).one()
            assert tuple(row) == (confirmation_id, "Preserve me", 0)
            assert tuple(
                connection.execute(
                    text("SELECT resolution_cycle, confirmation_count FROM incidents")
                ).one()
            ) == (1, 1)
        finally:
            connection.rollback()
            connection.execute(text("SET search_path TO public"))
            connection.execute(text(f"DROP SCHEMA {schema} CASCADE"))
            connection.commit()
    engine.dispose()


def test_postgres_concurrent_confirmations_and_cancel_race(photo):
    engine = create_engine(
        os.environ["INTEGRATION_DATABASE_URL"], connect_args={"connect_timeout": 10}
    )
    with httpx.Client(base_url=os.environ["INTEGRATION_API_URL"], timeout=30) as client:
        login = client.post(
            "/auth/register",
            json={
                "email": f"{uuid4()}@example.com",
                "password": "Synthetic-test-only!",
                "display_name": "Concurrency",
            },
        ).json()
        headers = {"Authorization": f"Bearer {login['access_token']}"}

        def payload():
            upload = client.post(
                "/uploads/images",
                headers=headers,
                files={"file": ("synthetic.jpg", photo, "image/jpeg")},
            )
            assert upload.status_code == 201
            return {
                "title": "Concurrent synthetic incident",
                "description": "Synthetic only",
                "category_id": "other",
                "latitude": 43.2,
                "longitude": 76.8,
                "severity": 3,
                "upload_ids": [upload.json()["id"]],
                "reviewed_by_user": True,
            }

        incident = client.post(
            "/incidents", headers=headers | {"Idempotency-Key": str(uuid4())}, json=payload()
        ).json()
        path = f"/incidents/{incident['id']}/confirmations"

        def confirm(_):
            return client.post(path, headers=headers, json={"status": "still_exists"})

        for cycle in range(3):
            if cycle:
                # The HTTP lifecycle is covered by API tests; here focus on PG locking.
                with engine.begin() as db:
                    db.execute(
                        text(
                            "UPDATE incidents SET status='resolved_pending_confirmation', resolution_cycle=:cycle WHERE id=:id"
                        ),
                        {"cycle": cycle, "id": incident["id"]},
                    )
            with ThreadPoolExecutor(max_workers=4) as pool:
                responses = list(pool.map(confirm, range(4)))
            assert sorted(r.status_code for r in responses) == [201, 409, 409, 409]
            details = client.get(f"/incidents/{incident['id']}").json()
            assert details["confirmation_count"] == 1
            if cycle:
                assert details["status"] == "under_review"
        with engine.connect() as db:
            assert (
                db.scalar(
                    text("SELECT count(*) FROM incident_confirmations WHERE incident_id=:id"),
                    {"id": incident["id"]},
                )
                == 3
            )
        racing_payload, key = payload(), str(uuid4())

        def send():
            return client.post(
                "/incidents", headers=headers | {"Idempotency-Key": key}, json=racing_payload
            )

        def cancel():
            return client.post(f"/incidents/publications/{key}/cancel", headers=headers)

        with ThreadPoolExecutor(max_workers=2) as pool:
            pending_send, pending_cancel = pool.submit(send), pool.submit(cancel)
            sent, cancelled = pending_send.result(), pending_cancel.result()
        assert cancelled.status_code == 200
        if cancelled.json()["status"] == "published":
            assert sent.status_code == 201
            assert cancelled.json()["incident"]["id"] == sent.json()["id"]
            assert send().json()["id"] == sent.json()["id"]
        else:
            assert sent.status_code == 409
            assert send().json()["error"]["code"] == "publication_cancelled"
    engine.dispose()
